import csv
for f in ["out/分项预算_20261122.csv","out/物料清单_20261122.csv","out/分工表_20261122.csv","out/当日排期表_20261122.csv"]:
    rows=list(csv.reader(open(f,encoding="utf-8")))
    ncol={len(r) for r in rows}
    print(f"{f}: 行数={len(rows)-1} 列数集合={ncol} 表头={rows[0]}")
for f in ["out/分项预算_20261122.csv","out/物料清单_20261122.csv"]:
    rows=list(csv.DictReader(open(f,encoding="utf-8")))
    tot=0; bad=[]
    for r in rows:
        if r["物料"] if "物料" in r else r["分项"]:
            pass
        q=int(r["数量"]); u=int(r["单价"]); s=int(r["小计"])
        if q*u!=s: bad.append(r)
        tot+=s
    print(f"  {f}: 逐行加总={tot} 小计错行={len(bad)}")
rows=list(csv.DictReader(open("out/当日排期表_20261122.csv",encoding="utf-8")))
prev=None; mono=True; gaps=[]
for r in rows:
    s,e=int(r["开始"]),int(r["结束"])
    if e<=s: mono=False
    if prev is not None and s!=prev: gaps.append((r["环节"],prev,s))
    prev=e
print(f"排期: 环节={len(rows)} 结束>开始={mono} 断裂={gaps} 覆盖={rows[0]['开始']}→{rows[-1]['结束']}")
EOF","description":"Re-verify CSV integrity and arithmetic"}

